#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_ARGS      65          /* maximum number of arguments allowed   */
#define MAX_STRLEN    1024        /* maximum length of any argument/prefix */

int main(int argc, char **argv)
{
    /* -------------------------------------------------------------
     * Argument count checks
     * ------------------------------------------------------------- */
    if (argc - 1 == 0) {               /* no user‑supplied arguments */
        puts("EMPTY");
        return 0;
    }
    if (argc - 1 > MAX_ARGS) {         /* too many arguments */
        puts("TOO_MANY");
        return 0;
    }

    /* -------------------------------------------------------------
     * Validate each argument length
     * ------------------------------------------------------------- */
    for (int i = 1; i < argc; ++i) {
        if (strlen(argv[i]) > MAX_STRLEN) {
            puts("TOO_LONG");
            return 0;
        }
    }

    /* -------------------------------------------------------------
     * Compute longest common prefix
     * ------------------------------------------------------------- */
    size_t prefix_len = strlen(argv[1]);   /* start with first argument */

    for (int i = 2; i < argc && prefix_len > 0; ++i) {
        /* Reduce prefix_len until it matches the start of argv[i] */
        while (prefix_len > 0 &&
               strncmp(argv[1], argv[i], prefix_len) != 0) {
            --prefix_len;
        }
    }

    /* -------------------------------------------------------------
     * Prefix length sanity check
     * ------------------------------------------------------------- */
    if (prefix_len > MAX_STRLEN) {
        puts("TOO_LONG");
        return 0;
    }

    /* -------------------------------------------------------------
     * Output the result
     * ------------------------------------------------------------- */
    if (prefix_len > 0) {
        /* Write the common prefix without an extra terminating '\0' */
        fwrite(argv[1], 1, prefix_len, stdout);
    }
    putchar('\n');   /* always terminate the output line */

    return 0;
}
